JS = """/* ================= projects ================= */
let connMode = "tools", editing = "", projState = { active: null, projects: [] };
const F = ["name", "jaeger", "prom", "host", "user", "key", "entry", "loki", "port", "compose", "services", "step", "base"];
function setConnMode(m) { connMode = m; document.querySelectorAll("#modeseg button").forEach(b => b.classList.toggle("on", b.dataset.v === m));
  $("g_tools").style.display = m === "ssh" ? "none" : ""; $("g_ssh").style.display = m === "tools" ? "none" : ""; }
document.querySelectorAll("#modeseg button").forEach(b => b.onclick = () => setConnMode(b.dataset.v));

async function refreshProjects(select) {
  projState = await (await fetch("/api/projects")).json();
  $("proj").innerHTML = projState.projects.length ? projState.projects.map(p => `<option value="${p.name}" ${p.name === projState.active ? "selected" : ""}>${p.name} (${p.mode})</option>`).join("")
                                                  : "<option value=''>none yet</option>";
  $("editbtn").disabled = !projState.projects.length;
}
async function openConn(name) {                       // name = existing project to edit, falsy = new project
  editing = name || ""; $("conn").style.display = "grid"; $("c_res").innerHTML = ""; $("c_msg").textContent = "";
  $("c_title").textContent = name ? "Edit project" : "New project"; $("c_del").style.display = name ? "" : "none";
