  $("c_msg").textContent = r.missing.length ? "Saved. Still needed: " + r.missing.join(", ") : "Saved. Testing…";
  const t = await (await fetch("/api/projects/" + encodeURIComponent(r.name) + "/test", { method: "POST" })).json();
  $("c_res").innerHTML = (t.results || []).map(x => `<div class="res"><span class="dot ${x.ok ? "ok-dot" : "bad-dot"}"></span><b>${x.source}</b><span class="muted">${x.detail}</span><span class="muted" style="margin-left:auto">${x.ms} ms</span></div>`).join("");
  if (t.results && t.results.length && t.results.every(x => x.ok)) { $("c_msg").textContent = "Connected."; document.querySelector('#srcseg button[data-v="live"]').click(); }
};
$("c_del").onclick = async () => { if (!confirm("Delete project '" + editing + "'?")) return;
  await fetch("/api/projects/" + encodeURIComponent(editing), { method: "DELETE" }); $("conn").style.display = "none"; await refreshProjects(); resetLive(); if (S.source === "live") load(); };

"""
s = s[:a] + JS + s[b:]
s = s.replace("$z.value = m.z;", "$z.value = m.z;")
# boot: load project list; source switch resets via resetLive-compatible code stays as is
s = s.replace("$(\"z\").value = m.z; $(\"zv\").textContent = m.z; resize();", "$(\"z\").value = m.z; $(\"zv\").textContent = m.z; await refreshProjects(); resize();")
# friendlier not-connected button
s = s.replace('onclick=\\"openConn()\\">Connect data source</button>', 'onclick=\\"openConn()\\">New project</button>')
s = s.replace('onclick="openConn()">Connect data source</button>', 'onclick="openConn()">New project</button>')
p.write_text(s, encoding="utf-8")
print("ok", "refreshProjects" in s, "connbtn" in s)

